CREATE TABLE IF NOT EXISTS migrations (id text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, email text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS organizations (id text PRIMARY KEY, name text NOT NULL, settings jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships (organization_id text NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('owner','admin','editor','analyst','viewer')), PRIMARY KEY(organization_id,user_id));
CREATE TABLE IF NOT EXISTS sessions (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, organization_id text NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, csrf text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS recovery_tokens (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE IF NOT EXISTS invitations (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, email text NOT NULL, role text NOT NULL CHECK(role IN ('admin','editor','analyst','viewer')), token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, accepted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS entities (organization_id text NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, id text NOT NULL, kind text NOT NULL, name text NOT NULL, data jsonb NOT NULL DEFAULT '{}', revision integer NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,id));
CREATE INDEX IF NOT EXISTS entities_kind ON entities(organization_id,kind,updated_at DESC);
CREATE TABLE IF NOT EXISTS products (organization_id text NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, id text NOT NULL, provider_id text NOT NULL, title text NOT NULL, data jsonb NOT NULL, synced_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,id), UNIQUE(organization_id,provider_id));
CREATE TABLE IF NOT EXISTS variants (organization_id text NOT NULL, id text NOT NULL, product_id text NOT NULL, title text NOT NULL, price integer NOT NULL CHECK(price>=0), inventory integer NOT NULL CHECK(inventory>=0), PRIMARY KEY(organization_id,id), FOREIGN KEY(organization_id,product_id) REFERENCES products(organization_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS templates (organization_id text NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, id text NOT NULL, name text NOT NULL, document jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, status text NOT NULL CHECK(status IN ('draft','published')) DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,id));
CREATE TABLE IF NOT EXISTS template_versions (organization_id text NOT NULL, template_id text NOT NULL, revision integer NOT NULL, document jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,template_id,revision), FOREIGN KEY(organization_id,template_id) REFERENCES templates(organization_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS connections (organization_id text NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, provider text NOT NULL, mode text NOT NULL CHECK(mode IN ('sandbox','live')), status text NOT NULL, credential text, metadata jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,provider));
CREATE TABLE IF NOT EXISTS action_tokens (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, recipient_id text NOT NULL, scope text NOT NULL, target_id text NOT NULL, token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, used_at timestamptz, result jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS tokens_tenant ON action_tokens(organization_id,recipient_id);
CREATE TABLE IF NOT EXISTS idempotency (organization_id text NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, key text NOT NULL, request_hash text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,key));
CREATE TABLE IF NOT EXISTS events (organization_id text NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, id text NOT NULL, recipient_id text NOT NULL, event_type text NOT NULL, template_id text, message_id text, campaign_id text, block_id text, provider_action_id text, revenue integer NOT NULL DEFAULT 0 CHECK(revenue>=0), currency text NOT NULL DEFAULT 'USD', cohort text, demo boolean NOT NULL DEFAULT false, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,id));
CREATE INDEX IF NOT EXISTS events_tenant_time ON events(organization_id,created_at,event_type);
CREATE TABLE IF NOT EXISTS experiment_assignments (organization_id text NOT NULL, experiment_id text NOT NULL, recipient_id text NOT NULL, cohort text NOT NULL CHECK(cohort IN ('control','treatment')), exposed_at timestamptz NOT NULL DEFAULT now(), converted_at timestamptz, PRIMARY KEY(organization_id,experiment_id,recipient_id), FOREIGN KEY(organization_id,experiment_id) REFERENCES entities(organization_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS submissions (organization_id text NOT NULL, id text NOT NULL, form_id text NOT NULL, recipient_id text NOT NULL, answers jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,id), FOREIGN KEY(organization_id,form_id) REFERENCES entities(organization_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS consent (organization_id text NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, id text NOT NULL, recipient_id text NOT NULL, channel text NOT NULL, address text NOT NULL, status text NOT NULL CHECK(status IN ('pending','confirmed','revoked')), wording text NOT NULL, evidence jsonb NOT NULL, confirmed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,id), UNIQUE(organization_id,channel,address));
CREATE TABLE IF NOT EXISTS audit_logs (organization_id text NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, id text NOT NULL, actor_id text NOT NULL, action text NOT NULL, target_id text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,id));
CREATE TABLE IF NOT EXISTS jobs (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, kind text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'queued', attempts integer NOT NULL DEFAULT 0, run_at timestamptz NOT NULL DEFAULT now(), last_error text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS webhook_events (provider text NOT NULL, event_id text NOT NULL, organization_id text NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, payload_hash text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(provider,event_id));
INSERT INTO migrations(id) VALUES ('001_initial') ON CONFLICT DO NOTHING;
ALTER TABLE action_tokens ADD COLUMN IF NOT EXISTS metadata jsonb NOT NULL DEFAULT '{}';
CREATE UNIQUE INDEX IF NOT EXISTS unique_recipient_review ON entities(organization_id,(data->>'recipientId'),(data->>'productId')) WHERE kind='review';
